import type { AuthIR, SpecIR } from "@smithable/core";
import { humanize } from "./naming.js";

const HEADER =
  "// Generated by Smithable from smithable.auth.yml. Do not edit: this file is overwritten on every change.\n";

/** Kit files that only apps with sign-in need. */
export const SIGN_IN_KIT = [
  "src/kit/SignIn.tsx",
  "src/lib/auth-client.ts",
  "src/routes/api/auth/$.ts",
];

export const hasSignIn = (auth: AuthIR) => auth.signIn !== "none";

const ENV: Record<string, [string, string]> = {
  google: ["GOOGLE_CLIENT_ID", "GOOGLE_CLIENT_SECRET"],
  facebook: ["FACEBOOK_CLIENT_ID", "FACEBOOK_CLIENT_SECRET"],
};

/** Development users get an address in an allowed domain, so they pass the sign-up check. */
function devDomain(auth: AuthIR): string {
  return (auth.signIn === "none" ? undefined : auth.signIn.allowedDomains?.[0]) ?? "example.com";
}

/** Better Auth's configuration: providers, the Drizzle tables, roles and sign-up rules. */
export function authModule(auth: AuthIR): string {
  if (auth.signIn === "none") throw new Error("No sign-in");
  const { providers, allowedDomains } = auth.signIn;
  const provider = (name: string) => {
    const [id, secret] = ENV[name] as [string, string];
    const hd =
      name === "google" && allowedDomains?.length === 1
        ? `, hd: ${JSON.stringify(allowedDomains[0])}`
        : "";
    return `  ...(process.env.${id} && process.env.${secret}
    ? { ${name}: { clientId: process.env.${id}, clientSecret: process.env.${secret}${hd} } }
    : {}),`;
  };
  const domainCheck = allowedDomains
    ? `
      if (!ALLOWED_DOMAINS.includes(email.split("@")[1] ?? "")) {
        throw new APIError("FORBIDDEN", {
          message: \`Only \${ALLOWED_DOMAINS.join(" and ")} accounts can sign in.\`,
        });
      }`
    : "";
  return `${HEADER}import { betterAuth } from "better-auth";
import { drizzleAdapter } from "better-auth/adapters/drizzle";
${allowedDomains ? 'import { APIError } from "better-auth/api";\n' : ""}import { tanstackStartCookies } from "better-auth/tanstack-start";
import { db } from "#/db";
import { account, session, user, verification } from "#/db/schema";

/** Sign-in providers in button order; each needs its keys in the environment (see the README). */
export const PROVIDERS = ${JSON.stringify(providers)};
${allowedDomains ? `const ALLOWED_DOMAINS = ${JSON.stringify(allowedDomains)};\n` : ""}/** These addresses become admins when they first sign in. */
const ADMINS: string[] = ${JSON.stringify(auth.admins)};

const socialProviders = {
${providers.map(provider).join("\n")}
};

/** The providers whose keys are set. */
export const configuredProviders = () => PROVIDERS.filter((p) => p in socialProviders);

export const auth = betterAuth({
  // In development the app runs on port 3000 (pnpm dev); set BETTER_AUTH_URL in production.
  baseURL: process.env.BETTER_AUTH_URL ?? (import.meta.env.DEV ? "http://localhost:3000" : undefined),
  database: drizzleAdapter(db, { provider: "sqlite", schema: { account, session, user, verification } }),
  socialProviders,
  // Email and password only serve the development sign-in; production builds leave it off.
  emailAndPassword: { enabled: import.meta.env.DEV },
  user: {
    additionalFields: {
      role: { type: "string", required: true, defaultValue: ${JSON.stringify(auth.defaultRole)}, input: false },
    },
  },
  databaseHooks: {
    user: {
      create: {
        before: async (newUser) => {
          const email = newUser.email.toLowerCase();${domainCheck}
          return { data: { ...newUser, role: ADMINS.includes(email) ? "admin" : ${JSON.stringify(auth.defaultRole)} } };
        },
      },
    },
  },
  plugins: [tanstackStartCookies()],
});
`;
}

/** The signed-in user of the current request; server-only. */
export function viewerModule(auth: AuthIR): string {
  if (!hasSignIn(auth)) {
    return `${HEADER}import type { Viewer } from "#/kit/access";

/** This app has no sign-in: every visitor is anonymous. */
export async function currentViewer(): Promise<Viewer | null> {
  return null;
}
`;
  }
  return `${HEADER}import { getRequestHeaders } from "@tanstack/react-start/server";
import type { Viewer } from "#/kit/access";
import { auth } from "#/lib/auth";

/** The signed-in user of the current request, or null. */
export async function currentViewer(): Promise<Viewer | null> {
  const session = await auth.api.getSession({ headers: getRequestHeaders() });
  if (!session) return null;
  const { id, name, email, role } = session.user;
  return { id, name, email, role };
}
`;
}

/** Everyone who can be chosen in a User field, e.g. an account manager. */
export function usersModule(): string {
  return `${HEADER}import { createServerFn } from "@tanstack/react-start";
import { asc } from "drizzle-orm";
import { db } from "#/db";
import { user } from "#/db/schema";
import { AccessDenied } from "#/kit/access";
import { currentViewer } from "#/lib/viewer.server";

/** Choices for fields that refer to a user; for signed-in users only. */
export const userOptions = createServerFn().handler(async () => {
  if (!(await currentViewer())) throw new AccessDenied(false);
  return db.select({ value: user.id, label: user.name }).from(user).orderBy(asc(user.name)).all();
});
`;
}

/** The sign-in page, with a development-only sign-in as any role. */
export function signInRoute(auth: AuthIR): string {
  const roles = auth.roles.map((r) => r.name);
  return `${HEADER}import { createFileRoute, useRouter } from "@tanstack/react-router";
import { createServerFn } from "@tanstack/react-start";
import { getRequestHeaders } from "@tanstack/react-start/server";
import { eq } from "drizzle-orm";
import { z } from "zod";
import { db } from "#/db";
import { user } from "#/db/schema";
import { app } from "#/generated/app";
import { SignIn } from "#/kit/SignIn";
import { auth, configuredProviders, PROVIDERS } from "#/lib/auth";
import { authClient } from "#/lib/auth-client";

const ROLES = ${JSON.stringify(roles)} as const;

const signInOptions = createServerFn().handler(() => {
  const providers = configuredProviders();
  return { providers, missing: PROVIDERS.filter((p) => !providers.includes(p)) };
});

/** Development only: signs in as a user with the role, without a provider. */
const devSignIn = createServerFn({ method: "POST" })
  .validator(z.enum(ROLES))
  .handler(async ({ data: role }) => {
    if (!import.meta.env.DEV) throw new Error("Only available in development.");
    const email = \`dev-\${role}@${devDomain(auth)}\`;
    const password = "dev-password";
    if (!db.select({ id: user.id }).from(user).where(eq(user.email, email)).get()) {
      await auth.api.signUpEmail({ body: { email, password, name: \`Dev \${role}\` } });
    }
    db.update(user).set({ role }).where(eq(user.email, email)).run();
    await auth.api.signInEmail({ body: { email, password }, headers: getRequestHeaders() });
  });

export const Route = createFileRoute("/sign-in")({
  // Only paths within the app, so the page cannot send anyone elsewhere.
  validateSearch: z.object({ redirect: z.string().regex(/^\\/(?!\\/)/).optional().catch(undefined) }),
  loader: () => signInOptions(),
  component: SignInPage,
});

function SignInPage() {
  const { providers, missing } = Route.useLoaderData();
  const { redirect = "/" } = Route.useSearch();
  const router = useRouter();
  return (
    <SignIn
      appName={app.name}
      providers={providers}
      missing={missing}
      devRoles={import.meta.env.DEV ? [...ROLES] : undefined}
      onProvider={async (provider) => {
        const { error } = await authClient.signIn.social({ provider, callbackURL: redirect });
        if (error) throw new Error(error.message);
      }}
      onDevRole={async (role) => {
        await devSignIn({ data: role as (typeof ROLES)[number] });
        await router.invalidate();
        await router.navigate({ href: redirect });
      }}
    />
  );
}
`;
}

/** Better Auth's tables, as its CLI would generate them, plus each user's role. */
export function authTables(auth: AuthIR): string {
  return `export const user = sqliteTable("user", {
  id: text().primaryKey(),
  name: text().notNull(),
  email: text().notNull().unique(),
  emailVerified: integer({ mode: "boolean" }).default(false).notNull(),
  image: text(),
  role: text().notNull().default(${JSON.stringify(auth.defaultRole)}),
  createdAt: integer({ mode: "timestamp_ms" }).notNull().$defaultFn(() => new Date()),
  updatedAt: integer({ mode: "timestamp_ms" })
    .notNull()
    .$defaultFn(() => new Date())
    .$onUpdate(() => new Date()),
});

export const session = sqliteTable(
  "session",
  {
    id: text().primaryKey(),
    expiresAt: integer({ mode: "timestamp_ms" }).notNull(),
    token: text().notNull().unique(),
    createdAt: integer({ mode: "timestamp_ms" }).notNull(),
    updatedAt: integer({ mode: "timestamp_ms" }).notNull(),
    ipAddress: text(),
    userAgent: text(),
    userId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (t) => [index("session_user_id_idx").on(t.userId)],
);

export const account = sqliteTable(
  "account",
  {
    id: text().primaryKey(),
    accountId: text().notNull(),
    providerId: text().notNull(),
    userId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text(),
    refreshToken: text(),
    idToken: text(),
    accessTokenExpiresAt: integer({ mode: "timestamp_ms" }),
    refreshTokenExpiresAt: integer({ mode: "timestamp_ms" }),
    scope: text(),
    password: text(),
    createdAt: integer({ mode: "timestamp_ms" }).notNull(),
    updatedAt: integer({ mode: "timestamp_ms" }).notNull(),
  },
  (t) => [index("account_user_id_idx").on(t.userId)],
);

export const verification = sqliteTable(
  "verification",
  {
    id: text().primaryKey(),
    identifier: text().notNull(),
    value: text().notNull(),
    expiresAt: integer({ mode: "timestamp_ms" }).notNull(),
    createdAt: integer({ mode: "timestamp_ms" }).notNull().$defaultFn(() => new Date()),
    updatedAt: integer({ mode: "timestamp_ms" })
      .notNull()
      .$defaultFn(() => new Date())
      .$onUpdate(() => new Date()),
  },
  (t) => [index("verification_identifier_idx").on(t.identifier)],
);`;
}

/** The README section on signing in: provider setup and the development sign-in. */
export function signInReadme(ir: SpecIR, auth: AuthIR): string {
  if (auth.signIn === "none") return "";
  const setup = auth.signIn.providers.map((p) => {
    const [id, secret] = ENV[p] as [string, string];
    const console =
      p === "google"
        ? "In the [Google Cloud console](https://console.cloud.google.com/apis/credentials), create an OAuth client ID of type *Web application*"
        : "In [Meta for Developers](https://developers.facebook.com/apps), create an app with *Facebook Login*";
    return `### ${humanize(p)}

1. ${console}.
2. Add the redirect URLs \`http://localhost:3000/api/auth/callback/${p}\` and \`https://<your domain>/api/auth/callback/${p}\`.
3. Put the keys in \`.env\` (never commit it):

   \`\`\`sh
   ${id}=...
   ${secret}=...
   \`\`\``;
  });
  return `
## Signing in

${ir.app.name} signs users in with ${auth.signIn.providers.map(humanize).join(" or ")}, through [Better Auth](https://www.better-auth.com). In development, the sign-in page also lets you sign in as any role (${auth.roles.map((r) => r.name).join(", ")}) without a provider; production builds leave that out.

In production, set \`BETTER_AUTH_SECRET\` (at least 32 random characters, e.g. \`openssl rand -base64 32\`) and \`BETTER_AUTH_URL\` (the app's public address) as well.

${setup.join("\n\n")}
`;
}
